import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for i in [1, 2, 3, 4, 5, 7, 8, 13]:
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
        print(f"\n=== Experiment {i} ===")
        print(f"Shape: {dfs[i].shape}")
        print(f"Columns: {list(dfs[i].columns)}")
        print(dfs[i].describe().round(2))
    except Exception as e:
        print(f"Exp {i}: {e}")

# Check what columns exist across experiments
all_cols = set()
for df in dfs.values():
    all_cols.update(df.columns)
print(f"\n\nAll columns ever measured: {sorted(all_cols)}")

# For each experiment, correlate with WaterClarityScore
for i, df in dfs.items():
    if 'WaterClarityScore' in df.columns:
        corr_cols = [c for c in df.columns if c != 'WaterClarityScore' and df[c].dtype in [np.float64, np.int64, float, int]}
        if corr_cols:
            print(f"\nExp {i} correlations with WaterClarityScore:")
            for c in corr_cols:
                if df[c].std() > 0:
                    r, p = stats.pearsonr(df[c], df['WaterClarityScore'])
                    print(f"  {c}: r={r:.3f}, p={p:.2e}")

